={{ (() => {
  const s = $json.slack || {};
  const texto = s.texto || '';
  const m = texto.match(/<(https?:\/\/[^>|]+)/);
  const url = (m && m[1]) || $json.url_live || 'https://portal.modofundraising.com/portal/clases';
  const titulo = $json.titulo || 'la sesión';
  const fechaFmt = $json.fecha
    ? DateTime.fromISO($json.fecha).setZone('America/Santiago').toFormat('dd/MM/yyyy · h:mm a')
    : 'Por confirmar';
  return JSON.stringify({
    channel: s.canal || '#modo-fundraising',
    text: `⏰ Tu sesión comienza en 1 hora: ${titulo}`,
    blocks: [
      { type: 'header', text: { type: 'plain_text', text: '⏰ Tu sesión comienza en 1 hora', emoji: true } },
      { type: 'section', fields: [
        { type: 'mrkdwn', text: `*📚 Sesión:*\n${titulo}` },
        { type: 'mrkdwn', text: `*🗓️ Fecha y hora (Santiago):*\n${fechaFmt}` }
      ] },
      { type: 'actions', elements: [
        { type: 'button', action_id: 'join_session', text: { type: 'plain_text', text: '🎥 Entrar a la sesión', emoji: true }, url, style: 'primary' }
      ] }
    ]
  });
})() }}
